def bands_of(g, out_h=3):
    h,w=len(g),len(g[0]); n=h//out_h; bs=[]
    for i in range(n):
        seg=g[i*out_h:(i+1)*out_h]
        col={v for row in seg for v in row if v}.pop()
        bs.append((col,seg))
    return bs
def comps(seg,col):
    h,w=len(seg),len(seg[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if seg[i][j]==col and (i,j) not in seen:
                st=[(i,j)]; seen.add((i,j)); c=[]
                while st:
                    a,b=st.pop(); c.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and seg[x][y]==col and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                out.append(c)
    return out
