def bbox(col,seg):
    cells=[(i,j) for i,r in enumerate(seg) for j,v in enumerate(r) if v==col]
    if not cells: return 0
    hs=[a for a,_ in cells]; ws=[b for _,b in cells]
    return (max(hs)-min(hs)+1)*(max(ws)-min(ws)+1)
