def solve(g):
    bs=bands_of(g)
    first=bs[0][1]
    bycol={c:seg for c,seg in bs}
    h,w=len(first),len(first[0])
    out=[[0]*w for _ in range(h)]
    for i in range(h):
        for j in range(w):
            if first[i][j]: out[i][j]=first[i][j]; continue
            on=[c for c,seg in bycol.items() if c!=first and seg[i][j]]
            out[i][j]=min(on,key=lambda c:PRIO[c]) if on else 0
    return out
